onClick:
{{
  (async function() {
    try {
      // 1. ACTION BASE DE DONNÉES
      const res = await Insert_Article_Rapide.run();
      const newId = res[0]?.ID_Article || res[0]?.id_article;

      await storeValue('nouvel_article_id', newId);
      await Get_Articles_Options.run(); 

      // 2. ACTIONS VISUELLES
      await closeModal('modal_add_article');
      await showModal('modal_add_devis'); // ⚠️ Vérifie si ta modale s'appelle 'modal_add_devis' ou 'modal_add_ligne'

      // 3. FORCE LE SELECT À SELECTIONNER LE NOUVEL ARTICLE
      resetWidget('sel_achat_article', true); // ⚠️ Remplace 'sel_achat_article' par le nom exact de ton Select
      resetWidget('modal_add_article', true);

      showAlert('Article créé et sélectionné !', 'success');

    } catch (error) {
      showAlert('Erreur : ' + error.message, 'error');
    }
  })()
}}
